```rust
struct Entry {
    value: f64,
    date: NaiveDate,
}
struct Account {
    entries: Vec<Entry>,
}
impl Account {
    fn get_flow_between(&self, start: NaiveDate, end: NaiveDate) -> f64 {
        let mut result = 0.0;
        for entry in &self.entries {
            // Feature Envy: manually extracting and comparing date boundaries
            if entry.date == start || entry.date == end || (entry.date > start && entry.date < end) {
                result += entry.value;
            }
        }
        result
    }
}
```

fix:
Introduce a `DateRange` struct and delegate the inclusion check to it.
```rust
struct DateRange {
    start: NaiveDate,
    end: NaiveDate,
}
impl DateRange {
    fn includes(&self, target: NaiveDate) -> bool {
        target >= self.start && target <= self.end
    }
}
impl Account {
    fn get_flow_between(&self, range: &DateRange) -> f64 {
        self.entries.iter()
            .filter(|e| range.includes(e.date))
            .map(|e| e.value)
            .sum()
    }
}
```
